/**
 * Stardust Runtime - Intercepts fetch requests and routes to Pyodide
 * Generated by stardust build
 */
(function() {
    'use strict';

    // Unregister any prior Service Workers + clear caches on every load so
    // dev rebuilds are picked up cleanly. Re-enable SW registration once the
    // bundle is stable (pass --enable-sw or similar flag in production).
    if ('serviceWorker' in navigator) {
        navigator.serviceWorker.getRegistrations().then(regs => {
            for (const r of regs) r.unregister();
        }).catch(() => {});
        if ('caches' in window) {
            caches.keys().then(keys => keys.forEach(k => caches.delete(k))).catch(() => {});
        }
    }

    const STARDUST_ROUTES = {
  "/": [
    "GET"
  ]
};
    const PYODIDE_URL = 'https://cdn.jsdelivr.net/pyodide/v0.29.1/full/';

    // Dynamic routes registered at runtime (e.g., by Starimo)
    const dynamicRoutes = {};

    let pyodide = null;
    let pyodideReady = false;
    let pendingRequests = [];

    /**
     * Register a route at runtime for interception.
     * Used by Starimo and other frameworks that add routes dynamically.
     * @param {string} pattern - Route pattern (e.g., "/starimo/sse")
     * @param {string[]} methods - HTTP methods (e.g., ["GET"])
     */
    window.__STARDUST_ADD_ROUTE__ = function(pattern, methods = ['GET']) {
        dynamicRoutes[pattern] = methods;
    };

    // Loading state management
    const loadingEl = document.getElementById('stardust-loading');
    const appEl = document.getElementById('stardust-app');

    function showApp() {
        if (loadingEl) loadingEl.style.display = 'none';
        if (appEl) appEl.style.display = 'block';
    }

    function updateLoadingStatus(message) {
        const statusEl = document.getElementById('stardust-status');
        if (statusEl) statusEl.textContent = message;
    }

    /**
     * Mount persistent filesystem at /data in Pyodide.
     * Tries OPFS first, falls back to IDBFS, then MEMFS.
     */
    async function setupPersistentFS(pyodide) {
        updateLoadingStatus('Setting up persistent storage...');

        // Try OPFS (modern browsers)
        if ('storage' in navigator && 'getDirectory' in navigator.storage) {
            try {
                const opfsRoot = await navigator.storage.getDirectory();
                const nativeFSModule = pyodide.FS.filesystems.NATIVEFS_ASYNC;

                if (nativeFSModule && pyodide.mountNativeFS) {
                    const opfsMount = await pyodide.mountNativeFS('/data', opfsRoot);
                    return {
                        type: 'opfs',
                        syncfs: () => opfsMount.syncfs()
                    };
                }
            } catch (e) {
                console.warn('OPFS mounting failed, trying IDBFS:', e.message);
            }
        }

        // Fall back to IDBFS (IndexedDB)
        // Create /data directory once for both IDBFS and MEMFS fallback
        pyodide.FS.mkdirTree('/data');
        try {
            pyodide.FS.mount(pyodide.FS.filesystems.IDBFS, {}, '/data');

            // Initial sync to populate from IndexedDB
            await new Promise((resolve, reject) => {
                pyodide.FS.syncfs(true, (err) => {
                    if (err) reject(err);
                    else resolve();
                });
            });

            return {
                type: 'idbfs',
                syncfs: () => new Promise((resolve, reject) => {
                    pyodide.FS.syncfs(false, (err) => {
                        if (err) reject(err);
                        else resolve();
                    });
                })
            };
        } catch (e) {
            // IDBFS failed, fall back to MEMFS
        }

        // Fall back to MEMFS (in-memory, no persistence)
        // Directory already created above
        return {
            type: 'memfs',
            syncfs: async () => {}
        };
    }

    function matchRoute(path) {
        // Check static routes (from build time)
        for (const pattern of Object.keys(STARDUST_ROUTES)) {
            const regex = patternToRegex(pattern);
            if (regex.test(path)) {
                return true;
            }
        }
        // Check dynamic routes (registered at runtime)
        for (const pattern of Object.keys(dynamicRoutes)) {
            const regex = patternToRegex(pattern);
            if (regex.test(path)) {
                return true;
            }
        }
        return false;
    }

    function patternToRegex(pattern) {
        // Convert /users/{user_id} to /users/[^/]+
        const escaped = pattern
            .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
            .replace(/\\{[^}]+\\}/g, '[^/]+');
        return new RegExp(`^${escaped}$`);
    }

    async function initPyodide() {
        updateLoadingStatus('Loading Python runtime...');

        pyodide = await loadPyodide({
            indexURL: PYODIDE_URL
        });

        // Setup persistent filesystem
        const fsConfig = await setupPersistentFS(pyodide);
        window.__STARDUST_FS__ = fsConfig;

        updateLoadingStatus('Installing dependencies...');

        await pyodide.loadPackage(["micropip", "ssl", "anyio", "msgspec", "pyodide-http", "jedi", "parso", "pygments", "docutils"]);

        // Install starhtml with WASM-compatible deps only (skip server deps like uvicorn/fastlite)
        const starhtmlWheel = new URL('static/starhtml-0.6.0-py3-none-any.whl', document.baseURI).href;
        await pyodide.runPythonAsync(`
import micropip
import sys
from types import ModuleType
from unittest.mock import MagicMock

# Create mock multiprocessing package (not available in Pyodide)
# fastcore.parallel imports: Process, Queue, Manager, set_start_method, get_all_start_methods, get_context
mp = ModuleType('multiprocessing')
mp.connection = MagicMock()
mp.queues = MagicMock()
mp.Queue = MagicMock()
mp.Process = MagicMock()
mp.Manager = MagicMock()
mp.set_start_method = MagicMock()
mp.get_all_start_methods = MagicMock(return_value=['fork', 'spawn'])
mp.get_context = MagicMock()
sys.modules['_multiprocessing'] = MagicMock()
sys.modules['multiprocessing'] = mp
sys.modules['multiprocessing.connection'] = mp.connection
sys.modules['multiprocessing.queues'] = mp.queues

# Mock concurrent.futures.process to avoid multiprocessing import
cf_process = ModuleType('concurrent.futures.process')
cf_process.ProcessPoolExecutor = object
sys.modules['concurrent.futures.process'] = cf_process

# Install WASM-compatible deps first
base_deps = ['starlette', 'httpx', 'beautifulsoup4', 'python-dateutil', 'fastcore', 'oauthlib', 'itsdangerous', 'python-multipart']
extra_packages = ["numpy", "matplotlib", "Markdown", "narwhals>=2.0", "packaging", "pymdown-extensions"]
all_deps = base_deps + extra_packages
await micropip.install(all_deps)

# Install starhtml without its deps (server deps don't work in Pyodide)
await micropip.install('${starhtmlWheel}', deps=False)
        `);

        // Install narwhals>=2.0 (marimo uses narwhals.stable.v2 which needs 2.0+)
        // Pyodide bundles an older version, so we explicitly upgrade
        await pyodide.runPythonAsync(`await micropip.install('narwhals>=2.0')`);

        // Install marimo with deps=False to skip msgspec version constraint
        // (Pyodide has msgspec 0.19.0, marimo wants >=0.20.0, but API is compatible)
        await pyodide.runPythonAsync(`await micropip.install('marimo', deps=False)`);

        // Install starimo from local wheel (not on PyPI)
        const starimoWheel = new URL('static/starimo-0.1.0-py3-none-any.whl', document.baseURI).href;
        await pyodide.runPythonAsync(`await micropip.install('${starimoWheel}', deps=False)`);

        updateLoadingStatus('Loading application...');

        // Load the starhtml app
        try {
            await pyodide.runPythonAsync(`
"""Pipeline + plot smoke test.

Verifies:
  1. Pyodide reactivity (Python \`\`@cell\`\` -> DOM via Datastar signal).
  2. micropip auto-dispatches numpy + matplotlib to prebuilt Pyodide wheels.
  3. \`\`@cell\`\` returning a matplotlib Figure renders inline as an image.

Once green, this scaffold becomes the home for the real notebook cells.
"""
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
from starhtml import Div, H1, H2, Input, P, Script, star_app
from starhtml.datastar import Signal
from starimo import cell
app, rt = star_app(title='Geometry of Noise', hdrs=(Script(src='https://cdn.tailwindcss.com'),))
n_sig = Signal('n', 8)
doubled_sig = Signal('doubled', 16)

@cell
def doubled(n: int=0):
    return n * 2

@cell
def smoke_plot(n: int=8):
    """One-off smoke test: returns a Figure that should render as an inline PNG."""
    rng = np.random.default_rng(0)
    theta = np.linspace(0, 2 * np.pi, max(int(n), 4) * 16)
    r = 1.0 + 0.05 * rng.standard_normal(theta.shape)
    x, y = (r * np.cos(theta), r * np.sin(theta))
    fig, ax = plt.subplots(figsize=(3.5, 3.5), dpi=110)
    ax.plot(x, y, lw=0.8, color='black')
    ax.set_aspect('equal')
    ax.set_xticks([])
    ax.set_yticks([])
    ax.set_title(f'unit ring, n*16 samples (n={n})')
    fig.tight_layout()
    return fig

@rt('/')
def home():
    return Div(H1('Geometry of Noise', cls='text-3xl font-bold mb-2'), H2('Plot pipeline smoke test', cls='text-xl text-gray-600 mb-6'), P('Two cells run in Pyodide: ', '\`\`doubled\`\` (scalar) and \`\`smoke_plot\`\` (matplotlib Figure). ', 'Change \`\`n\`\` to drive both.', cls='mb-4'), Div(Input(type='number', data_bind=n_sig, cls='border px-2 py-1 rounded'), Div('doubled = ', Div(data_text=doubled_sig, cls='inline font-mono'), cls='mt-2'), cls='p-4 border rounded bg-gray-50 mb-4'), Div(id='output-content-smoke_plot', cls='p-4 border rounded bg-white min-h-[300px]'), n_sig, doubled_sig, cls='max-w-2xl mx-auto p-8')
            `);
        } catch (e) {
            console.error('Error loading app:', e);
            throw e;
        }

        // Set up the request handler bridge (async for WASM compatibility)
        // Includes streaming response detection and stream registry
        await pyodide.runPythonAsync(`
import json

# Stream registry for managing streaming response lifecycles
_stardust_streams = {}
_stardust_stream_counter = 0

async def __stardust_handle_request(method, path, body, headers_json):
    """Bridge function called from JavaScript. Detects streaming responses."""
    global _stardust_stream_counter
    headers = json.loads(headers_json) if headers_json else {}

    response = await app.handle_request(method, path, body, headers)

    # Detect StreamingResponse by checking for body_iterator
    is_streaming = hasattr(response, 'body_iterator')

    result = {
        'streaming': is_streaming,
        'status': response.status_code,
        'headers': dict(response.headers)
    }

    if is_streaming:
        # Register the stream and return handle
        _stardust_stream_counter += 1
        stream_id = f"stream_{_stardust_stream_counter}"
        _stardust_streams[stream_id] = response.body_iterator
        result['stream_id'] = stream_id
    else:
        result['body'] = response.body.decode() if isinstance(response.body, bytes) else response.body

    return json.dumps(result)


async def __stardust_read_chunk(stream_id):
    """Pull next chunk from a registered stream."""
    gen = _stardust_streams.get(stream_id)
    if gen is None:
        return json.dumps({'done': True, 'error': 'Stream not found'})

    try:
        chunk = await gen.__anext__()
        chunk_str = chunk.decode() if isinstance(chunk, bytes) else chunk
        return json.dumps({'done': False, 'chunk': chunk_str})
    except StopAsyncIteration:
        # Clean up completed stream
        _stardust_streams.pop(stream_id, None)
        return json.dumps({'done': True})
    except Exception as e:
        # Clean up on error and report
        _stardust_streams.pop(stream_id, None)
        return json.dumps({'done': True, 'error': str(e)})


def __stardust_cleanup_stream(stream_id):
    """Clean up a stream on cancellation."""
    _stardust_streams.pop(stream_id, None)
        `);

        pyodideReady = true;
        updateLoadingStatus('Fetching page...');

        // Process any pending requests
        for (const { resolve, reject, args } of pendingRequests) {
            try {
                const response = await handleWithPyodide(...args);
                resolve(response);
            } catch (e) {
                reject(e);
            }
        }
        pendingRequests = [];

        // Initial HTML injection.
        // When stardust pre-renders `/` at build time, the full app HTML is
        // already baked into `<div id="stardust-app">` and Datastar scanned
        // it at page load — no runtime injection needed. This is the normal
        // fast path.
        // Fallback: when pre-render is disabled or failed, fetch `/` from the
        // Pyodide-hosted handler and inject via DOMParser + detach/reattach
        // to force Datastar's MutationObserver to scan the subtree.
        // Pre-render at build time populated #stardust-app.
        // Still detach/reattach so Datastar's MutationObserver
        // scans the subtree and wires data-text / data-bind.
        if (appEl) {
            const appParent = appEl.parentNode;
            const appNext = appEl.nextSibling;
            appParent.removeChild(appEl);
            if (appNext) appParent.insertBefore(appEl, appNext);
            else appParent.appendChild(appEl);
        }

        // Initialize starimo kernel AFTER HTML is in place
        // so kernel signals land on wired Datastar effects.
        // Starimo WASM integration - reactive notebook kernel
        // Register routes for starimo endpoints
        window.__STARDUST_ADD_ROUTE__('/starimo/sse', ['GET']);
        window.__STARDUST_ADD_ROUTE__('/starimo/sync', ['POST']);

        // Import Datastar functions for signal management
        // Runtime.js is in /static/, so datastar.js is in same directory
        const { mergePatch, getPath, effect } = await import('./datastar.js');

        // Initialize __stardust__ namespace for all Stardust/Starimo integration
        // This consolidates all globals under a single namespace
        window.__stardust__ = window.__stardust__ || {};
        window.__stardust__.starimo = {
            bridge: null,  // Will be set by Python after kernel init
            watchedSignals: [],
            pendingSync: {},
            previousValues: new Map(),

            // Callback for Python to update Datastar signals (Python → JS)
            onSignalUpdate: function(name, value) {
                // Track the value to avoid echo when we sync back
                this.previousValues.set(name, value);
                // Use Datastar's mergePatch to update signals reactively
                mergePatch({ [name]: value });

                // Auto-discover signals: set up watcher for any signal Python emits
                // Skip internal starimo_ signals (status, ready, etc.)
                if (!name.startsWith('starimo_') && !this.watchedSignals.includes(name)) {
                    this.setupSignalWatchers([name]);
                }
            },

            // Run arbitrary Python code in a dynamic cell
            // Returns the cell_id for tracking output via signals
            runCode: async function(code, cellId = '__user__') {
                if (!this.bridge) {
                    throw new Error('Starimo bridge not initialized');
                }
                // Use pyodide.globals.set() for safe parameter passing (no string escaping)
                pyodide.globals.set('_code', code);
                pyodide.globals.set('_cell_id', cellId);
                return await pyodide.runPythonAsync(`
import js
await js.window.__stardust__.starimo.bridge.run_user_code(_code, _cell_id)
                `);
            },

            // Create an editable cell (registers it with marimo)
            createCell: async function(cellId, initialCode = '') {
                if (!this.bridge) {
                    throw new Error('Starimo bridge not initialized');
                }
                // Use pyodide.globals.set() for safe parameter passing (no string escaping)
                pyodide.globals.set('_cell_id', cellId);
                pyodide.globals.set('_initial_code', initialCode);
                return await pyodide.runPythonAsync(`
import js
await js.window.__stardust__.starimo.bridge.create_editable_cell(_cell_id, _initial_code)
                `);
            },

            // Get cell output (for polling after execution)
            getCellOutput: function(cellId) {
                if (!this.bridge) {
                    throw new Error('Starimo bridge not initialized');
                }
                const result = this.bridge.get_cell_output(cellId);
                // Convert Pyodide proxy to JS object
                return result.toJs ? result.toJs() : result;
            },

            // Adaptive debounce configuration by input type (values from Python constants)
            debounceDelays: {
                text: 300,
                number: 300,
                spinner: 75,
                range: 32,
                immediate: 0,
                default: 200
            },

            // Per-signal timers and input type tracking
            signalTimers: {},
            signalInputTypes: {},
            isTyping: false,
            typingTimer: null,

            // Detect input type for a signal by scanning DOM
            detectInputType: function(signalName) {
                if (this.signalInputTypes[signalName]) {
                    return this.signalInputTypes[signalName];
                }

                // Find element with data-bind matching this signal
                const el = document.querySelector(`[data-bind="${signalName}"], [data-model="${signalName}"]`);
                if (!el) {
                    this.signalInputTypes[signalName] = 'default';
                    return 'default';
                }

                const tag = el.tagName.toLowerCase();
                const type = (el.type || '').toLowerCase();

                let inputType = 'default';
                if (tag === 'input') {
                    if (['text', 'password', 'email', 'search', 'url', 'tel'].includes(type)) {
                        inputType = 'text';
                    } else if (type === 'number') {
                        inputType = 'number';  // Will check isTyping dynamically
                    } else if (type === 'range') {
                        inputType = 'range';
                    } else if (['checkbox', 'radio'].includes(type)) {
                        inputType = 'immediate';
                    }
                } else if (tag === 'textarea') {
                    inputType = 'text';
                } else if (tag === 'select') {
                    inputType = 'immediate';
                }

                this.signalInputTypes[signalName] = inputType;
                return inputType;
            },

            // Get adaptive delay based on input type and context
            getDelay: function(signalName) {
                const inputType = this.detectInputType(signalName);

                // Number inputs: use shorter delay if clicking spinner, longer if typing
                if (inputType === 'number') {
                    return this.isTyping ? this.debounceDelays.number : this.debounceDelays.spinner;
                }

                return this.debounceDelays[inputType] ?? this.debounceDelays.default;
            },

            // Queue a signal change to sync to Python (JS → Python)
            queueSync: function(name, value) {
                // Normalize value (match non-WASM behavior)
                let syncValue = value;
                if (value === null || value === undefined || value === '') {
                    syncValue = 0;
                } else if (typeof value === 'string' && !isNaN(Number(value))) {
                    syncValue = Number(value);
                }

                this.pendingSync[name] = syncValue;
                if (this.signalTimers[name]) clearTimeout(this.signalTimers[name]);

                const delay = this.getDelay(name);
                if (delay === 0) {
                    this.flushSync();
                    return;
                }
                this.signalTimers[name] = setTimeout(() => {
                    delete this.signalTimers[name];
                    this.flushSync();
                }, delay);
            },

            // Send pending signal changes to Python
            flushSync: async function() {
                if (Object.keys(this.pendingSync).length === 0) return;

                const signals = { ...this.pendingSync };
                this.pendingSync = {};

                try {
                    await pyodide.runPythonAsync(`
import js
import json
import asyncio

signals = json.loads('${JSON.stringify(signals).replace(/'/g, "\'")}')
stardust = getattr(js.window, '__stardust__', None)
starimo_ns = getattr(stardust, 'starimo', None) if stardust else None
bridge = getattr(starimo_ns, 'bridge', None) if starimo_ns else None

if bridge:
    for name, value in signals.items():
        asyncio.create_task(bridge.set_input(name, value))
                    `);
                } catch (e) {
                    console.error('[Stardust] Signal sync error:', e);
                }
            },

            // Set up watchers for frontend signals (to detect user input changes)
            setupSignalWatchers: function(signalNames) {
                const newSignals = signalNames.filter(s => !this.watchedSignals.includes(s));
                if (newSignals.length === 0) return;

                this.watchedSignals.push(...newSignals);

                const self = this;
                for (const signalName of newSignals) {
                    // Register the effect in a fresh macrotask. Registering
                    // inside the Python→JS callback chain (pyodide.code.run_js)
                    // queues the effect before Datastar's reactivity graph is
                    // ready to track its reads, so its callback never re-fires
                    // on signal changes. setTimeout(fn, 0) escapes the pyodide
                    // call stack; queueMicrotask is NOT sufficient.
                    setTimeout(() => {
                        let initialValue = undefined;
                        try { initialValue = getPath(signalName); } catch {}
                        self.previousValues.set(signalName, initialValue);

                        let callCount = 0;
                        effect(() => {
                            callCount++;
                            let value;
                            try { value = getPath(signalName); } catch { return; }
                            const prevValue = self.previousValues.get(signalName);
                            if (value !== prevValue) {
                                self.previousValues.set(signalName, value);
                                // Skip the setup fire (callCount === 1); only
                                // sync real user-driven changes back to Python.
                                if (callCount > 1) self.queueSync(signalName, value);
                            }
                        });
                    }, 0);
                }
            }
        };

        // Bind methods to preserve 'this' context
        const starimo = window.__stardust__.starimo;
        starimo.onSignalUpdate = starimo.onSignalUpdate.bind(starimo);
        starimo.runCode = starimo.runCode.bind(starimo);
        starimo.createCell = starimo.createCell.bind(starimo);
        starimo.getCellOutput = starimo.getCellOutput.bind(starimo);
        starimo.queueSync = starimo.queueSync.bind(starimo);
        starimo.flushSync = starimo.flushSync.bind(starimo);
        starimo.setupSignalWatchers = starimo.setupSignalWatchers.bind(starimo);
        starimo.detectInputType = starimo.detectInputType.bind(starimo);
        starimo.getDelay = starimo.getDelay.bind(starimo);

        // Track keyboard activity to distinguish typing from spinner clicks
        document.addEventListener('keydown', () => {
            starimo.isTyping = true;
            if (starimo.typingTimer) clearTimeout(starimo.typingTimer);
        });
        document.addEventListener('keyup', () => {
            if (starimo.typingTimer) clearTimeout(starimo.typingTimer);
            starimo.typingTimer = setTimeout(() => {
                starimo.isTyping = false;
            }, 150);  // Reset typing flag
        });

        // Load pre-generated marimo notebook into Pyodide filesystem
        // The notebook was generated at build time by AST analysis,
        // which extracts cell source code (inspect.getsource fails in Pyodide)
        updateLoadingStatus('Loading reactive notebook...');
        const notebookResponse = await fetch('./static/__marimo__/app.py');
        const notebookCode = await notebookResponse.text();
        pyodide.FS.mkdirTree('/__marimo__');
        pyodide.FS.writeFile('/__marimo__/app.py', notebookCode);
        console.log('[Stardust] Notebook loaded into virtual filesystem');

        // Initialize starimo kernel with the pre-generated notebook
        updateLoadingStatus('Initializing reactive cells...');
        await pyodide.runPythonAsync(`
from starimo.wasm import init_kernel
await init_kernel("/__marimo__/app.py")
        `);
        console.log('[Stardust] Starimo kernel initialized');

        showApp();
    }

    async function handleWithPyodide(url, method, body, headers) {
        const path = new URL(url, window.location.origin).pathname;
        const headersObj = Object.fromEntries(headers.entries());
        const headersJson = JSON.stringify(headersObj);

        // Single call to detect response type
        const resultJson = await pyodide.runPythonAsync(
            `await __stardust_handle_request(${JSON.stringify(method)}, ${JSON.stringify(path)}, ${JSON.stringify(body || '')}, ${JSON.stringify(headersJson)})`
        );
        const result = JSON.parse(resultJson);

        // Non-streaming response - return immediately
        if (!result.streaming) {
            return new Response(result.body, {
                status: result.status,
                headers: new Headers(result.headers)
            });
        }

        // Streaming response - create ReadableStream
        const streamId = result.stream_id;
        const encoder = new TextEncoder();

        const stream = new ReadableStream({
            async pull(controller) {
                try {
                    const chunkJson = await pyodide.runPythonAsync(
                        `await __stardust_read_chunk(${JSON.stringify(streamId)})`
                    );
                    const chunk = JSON.parse(chunkJson);

                    if (chunk.error) {
                        console.error('[Stardust] Stream error:', chunk.error);
                        controller.close();
                        return;
                    }

                    if (chunk.done) {
                        controller.close();
                    } else {
                        controller.enqueue(encoder.encode(chunk.chunk));
                    }
                } catch (error) {
                    console.error('[Stardust] Pull error:', error);
                    controller.error(error);
                    // Cleanup on error
                    await pyodide.runPythonAsync(
                        `__stardust_cleanup_stream(${JSON.stringify(streamId)})`
                    );
                }
            },

            cancel(reason) {
                console.log('[Stardust] Stream cancelled:', reason);
                // Cleanup on client disconnect
                pyodide.runPythonAsync(
                    `__stardust_cleanup_stream(${JSON.stringify(streamId)})`
                ).catch(err => console.warn('[Stardust] Cleanup error:', err));
            }
        }, new CountQueuingStrategy({ highWaterMark: 3 }));

        // Merge SSE headers with response headers
        const responseHeaders = new Headers(result.headers);
        if (!responseHeaders.has('Content-Type')) {
            responseHeaders.set('Content-Type', 'text/event-stream');
        }
        if (!responseHeaders.has('Cache-Control')) {
            responseHeaders.set('Cache-Control', 'no-cache');
        }

        return new Response(stream, {
            status: result.status,
            headers: responseHeaders
        });
    }

    const originalFetch = window.fetch;

    window.fetch = async function(input, init = {}) {
        const url = typeof input === 'string' ? input : input.url;
        const urlObj = new URL(url, window.location.origin);

        // Only intercept same-origin requests to stardust routes
        if (urlObj.origin === window.location.origin && matchRoute(urlObj.pathname)) {
            const method = init.method || 'GET';
            const body = init.body || '';
            const headers = new Headers(init.headers || {});

            if (!pyodideReady) {
                // Queue the request until Pyodide is ready
                return new Promise((resolve, reject) => {
                    pendingRequests.push({
                        resolve,
                        reject,
                        args: [url, method, body, headers]
                    });
                });
            }

            return handleWithPyodide(url, method, body, headers);
        }

        // Pass through to original fetch for non-stardust routes
        return originalFetch.call(window, input, init);
    };

    initPyodide().catch(err => {
        console.error('Failed to initialize Stardust:', err);
        updateLoadingStatus('Error loading Python runtime');
    });
})();
